// One line of serial output from the Teensy.
// Only lines that start with '{' are the JSON telemetry (menu m -> j on the Teensy);
// all other lines (menus, messages) are ignored.
const line = String(msg.payload || '').trim();
if (!line.startsWith('{')) {
    // text (start banner, menu, messages): the Teensy lives, but sends no JSON right now
    if (line) flow.set('teensyLastText', Date.now());
    return null;
}
let d;
try {
    d = JSON.parse(line);
} catch (e) {
    node.status({ fill: 'red', shape: 'ring', text: 'invalid JSON' });
    return null;
}
d._ts = Date.now();
d._dvcc = flow.get('dvcc') || null;   // DVCC charge voltage limit (from the GX, see "DVCC values")
flow.set('teensyLastData', d._ts);
global.set('bmsMain', d);   // for the page 'Overzicht'
flow.set('teensyFw', 'v' + d.fw);
flow.set('teensyHw', d.hw || 'T32');   // Teensy model (firmware before v26.26 has no hw field: always a Teensy 3.2)
// Report this Teensy for the port assignment ("Assign Teensy ports" in the main tab)
const sm = String(flow.get('teensyPort') || '').match(/_([0-9A-Za-z]+)-if\d+$/);
if (sm) {
    const info = global.get('teensyInfo') || {};
    info[sm[1]] = { me: d.me || 0, hw: d.hw || 'T32', ts: d._ts };
    global.set('teensyInfo', info);
}
node.status({ fill: 'green', shape: 'dot', text: `v${d.fw}  ${d.so}/${d.se} strings  ${d.lo}-${d.hi} V` });

// History charts: every message goes to the "History buffer" (which keeps one point per 30 s)
// (only once the Teensy ports are assigned for sure, so no data of the other Teensy ends up in it)
if (!global.get('teensyRolesOk')) return [{ payload: d }, null];
return [{ payload: d }, { payload: { t: d._ts, hi: d.hi, lo: d.lo, hiid: d.hiid, loid: d.loid, v: d.v, cvl: d.cvl } }];

// Keeps 24 h of history (one point per 30 s) for the two history charts.
// Values in mV (integers), null = no value; hiid/loid = which cell ("Pk5 C6"). The dashboard replays the last
// message to every new browser, so a newly opened page shows the full history.
//
// Survives a restart of Node-RED / the Cerbo: every 10 minutes the history is
// written to a file (output 3 -> "save history"); at start "load history"
// reads it back (msg.topic 'restore').
//
// Outputs: 1 = cell chart, 2 = voltage/CVL chart, 3 = file
const KEEP = 24 * 3600, STEP = 30, SAVE_EVERY = 600;
const KEYS = ['hi', 'lo', 'v', 'cvl', 'hiid', 'loid'];

const empty = () => ({ t: [], hi: [], lo: [], v: [], cvl: [], hiid: [], loid: [] });
let h = context.get('h');
if (!h || !Array.isArray(h.t) || !KEYS.every(k => Array.isArray(h[k]))) h = empty();

function trim(now) {
    let k = 0;
    while (k < h.t.length && h.t[k] < now - KEEP) k++;
    if (k) { h.t.splice(0, k); for (const key of KEYS) h[key].splice(0, k); }
}
function charts() {
    return [
        { payload: { t: h.t.slice(), hi: h.hi.slice(), lo: h.lo.slice(), hiid: h.hiid.slice(), loid: h.loid.slice() } },
        { payload: { t: h.t.slice(), v: h.v.slice(), cvl: h.cvl.slice() } }
    ];
}
const mv = x => (x === null || x === undefined || isNaN(x)) ? null : Math.round(x * 1000);
// a cell below 1.0 V or above 4.5 V cannot be real (restart of the Teensy, broken CMU): no point
const mvCell = x => (x === null || x === undefined || isNaN(x) || x < 1.0 || x > 4.5) ? null : Math.round(x * 1000);
const now = Math.round(Date.now() / 1000);

if (msg.topic === 'restore') {
    let f;
    try { f = JSON.parse(msg.payload); } catch (e) { return null; }
    if (!f || !Array.isArray(f.t)) return null;
    // merge: file points that are older than what we already have in memory
    const first = h.t.length ? h.t[0] : Infinity;
    const r = empty();
    for (let i = 0; i < f.t.length; i++) {
        if (f.t[i] >= first || f.t[i] < now - KEEP) continue;
        r.t.push(f.t[i]);
        for (const key of KEYS) r[key].push(Array.isArray(f[key]) && f[key][i] !== undefined ? f[key][i] : null);
    }
    r.t = r.t.concat(h.t);
    for (const key of KEYS) r[key] = r[key].concat(h[key]);
    h = r;
    context.set('h', h);
    node.status({ fill: 'green', shape: 'dot', text: `restored, ${h.t.length} points` });
    return [...charts(), null];
}

const p = msg.payload;
if (!p) return null;
const t = Math.round((p.t || Date.now()) / 1000);
const last = h.t.length ? h.t[h.t.length - 1] : 0;
if (t - last < STEP) return null;
h.t.push(t);
const hiv = mvCell(p.hi), lov = mvCell(p.lo);
h.hi.push(hiv);
h.lo.push(lov);
h.hiid.push(hiv === null ? null : (p.hiid || null));
h.loid.push(lov === null ? null : (p.loid || null));
h.v.push(mv(p.v));
h.cvl.push(mv(p.cvl));
trim(t);
context.set('h', h);
node.status({ fill: 'green', shape: 'dot', text: `${h.t.length} points` });

let save = null;
const lastSave = context.get('saved');
if (!lastSave) context.set('saved', t);   // first save 10 min after start (after the restore)
else if (t - lastSave >= SAVE_EVERY && h.t.length > 1) {
    context.set('saved', t);
    save = { payload: JSON.stringify(h) };
}
return [...charts(), save];

// Assigns the Teensy USB ports: main battery (this tab) and test bench (tab "Tesla BMS Test").
// A Teensy is recognised by its USB serial number (/dev/serial/by-id/...-<serial>-if00).
// The assignment is saved in a file, so a restart of the GX never swaps them.
// First assignment with more than one Teensy and nothing saved yet: both are opened, and as
// soon as both send data the one with the most modules ("me" in the JSON) becomes the main battery.
// To assign again: delete teslabms-teensy-roles.json in the Node-RED folder and restart Node-RED.
const out = String(msg.payload || '');
const get = (k) => { const m = out.match(new RegExp('^' + k + '=(.*)$', 'm')); return m ? m[1].trim() : ''; };
const udev = get('UDEV'), rc = get('RCLOCAL');
const perm = (udev === 'noperm' || rc === 'noperm') ? '  (no rights: run install-teensy-ignore.sh once via SSH)' : '';
const ports = (out.match(/^PORT=.+$/mg) || []).map(l => l.slice(5).trim()).filter(Boolean);
const serialOf = (p) => { const m = p.match(/_([0-9A-Za-z]+)-if\d+$/); return m ? m[1] : p; };
const bySerial = {};
ports.forEach(p => { bySerial[serialOf(p)] = p; });
const serials = Object.keys(bySerial).sort();
const roles = Object.assign({}, global.get('teensyRoles') || {});
const info = global.get('teensyInfo') || {};
const now = Date.now();
const fresh = (s) => !!(info[s] && (now - info[s].ts) < 120000);

// Tab variable TESLABMS_MAIN_TEENSY = USB serial number of the main battery Teensy (empty = automatic)
const forced = String(env.get('TESLABMS_MAIN_TEENSY') || '').trim();
let main = (roles.main && bySerial[roles.main]) ? roles.main : null;
if (forced && bySerial[forced]) main = forced;
let sure = !!main;
if (main) context.set('mainGoneSince', 0);
if (!main) {
    // The saved main Teensy is not there. Normally the test Teensy never becomes the main one
    // (a short absence, e.g. a restart or firmware update of the main Teensy, must not swap them).
    // Gone for more than 2 minutes (replaced / broken): any Teensy may take over the main role.
    let goneLong = true;
    if (roles.main) {
        const since = context.get('mainGoneSince') || now;
        context.set('mainGoneSince', since);
        goneLong = now - since > 120000;
    }
    let cands = serials.filter(s => s !== roles.test);
    if (!cands.length && goneLong) cands = serials.slice();
    if (cands.length === 1) {
        main = cands[0]; sure = true;
    } else if (cands.length > 1) {
        const best = cands.every(fresh) ? cands.slice().sort((x, y) => (info[y].me || 0) - (info[x].me || 0)) : null;
        if (best && (info[best[0]].me || 0) > (info[best[1]].me || 0)) {
            main = best[0];      // clearly the most modules
            sure = true;
        } else {
            const prev = flow.get('mainSerial');
            main = (prev && cands.includes(prev)) ? prev : cands[0];   // provisional
        }
    }
}
// Safety net: a saved assignment where the test bench Teensy clearly has more modules than the
// main one (e.g. saved while both tabs read the same Teensy) is corrected.
if (main && roles.main === main) {
    const other = serials.find(s => s !== main);
    if (other && fresh(main) && fresh(other) && (info[other].me || 0) > (info[main].me || 0)) {
        main = other;
        roles.test = null;
    }
}
let test = (roles.test && bySerial[roles.test] && roles.test !== main) ? roles.test : (serials.find(s => s !== main) || null);
if (test === main) test = null;   // never the same Teensy for both tabs
flow.set('mainSerial', main);
global.set('teensyRolesOk', sure || !!roles.main);   // saved assignment: the ports are known even if one Teensy is unplugged

let save = null;
if (sure && (roles.main !== main || (test && roles.test !== test))) {
    const r = { main: main, test: test || (roles.test !== main ? roles.test : null) || null, saved: new Date().toISOString() };
    global.set('teensyRoles', r);
    save = { payload: JSON.stringify(r) };
}

// main battery port (reconnect when there is no data at all for 10 min, at most once per 10 min;
// a USB reconnect of the Teensy itself is handled by the port check, the path then changes)
let m1 = null;
const mainPort = main ? bySerial[main] : null;
if (mainPort) {
    const cur = flow.get('teensyPort');
    const silent = (now - Math.max(flow.get('teensyLastData') || 0, flow.get('teensyLastText') || 0)) > 600000;
    const lr = context.get('lastReconnect') || 0;
    if (mainPort !== cur || (silent && now - lr > 600000)) {
        if (mainPort !== cur) { flow.set('teensyHw', null); flow.set('teensyFw', null); }   // other Teensy: model/version unknown until its data arrives
        flow.set('teensyPort', mainPort);
        context.set('lastReconnect', now);
        m1 = { payload: mainPort + ' /data/home/nodered/.node-red/teslabms-tty-main' };   // -> ln -sfn <Teensy> <main link> -> reopen
    }
}
const short = (s) => s ? s : '-';
node.status({ fill: !mainPort ? 'red' : (perm ? 'yellow' : (sure ? 'green' : 'yellow')), shape: mainPort ? 'dot' : 'ring',
    text: (mainPort ? '' : 'main Teensy not found  ') + 'main ' + short(main) + (sure ? '' : ' (provisional)') + '  test ' + short(test) + '  udev:' + udev + perm });
return [m1, { payload: test ? bySerial[test] : '' }, save];

// Buttons from the "Updates" template and the periodic check (outputs: check, fw, flow, ui, Teensy serial).
// Updates need a double click: the second click must come within 10 s.
const now = Date.now();
const t = msg.topic;
const ui = (text) => ({ payload: { kind: 'state', text: text } });
if (t === 'check') {
    // ignore a second check while one is running (max 150 s, the exec times out at 120 s)
    const busy = flow.get('teslabmsChecking');
    if (busy && (now - busy) < 150000) return [null, null, null, ui('Checking versions... (already running)')];
    flow.set('teslabmsChecking', now);
    return [{ payload: '' }, null, null, ui('Checking versions...')];
}
if (t === 'cells') {
    // cells in series per string: 6 = 24 V, 12 = 48 V. Double click (10 s).
    const c = [6, 12].includes(Number(msg.payload)) ? Number(msg.payload) : 0;
    if (!c) return [null, null, null, ui('Battery voltage: invalid value'), null];
    const armed = context.get('armedCells') || {};
    if (armed.c === c && (now - armed.at) < 10000) {
        context.set('armedCells', {});
        return [null, null, null, ui('Sent: ' + c + ' cells in series (' + (c * 4) + ' V nominal) - strings are counted again (needs firmware v26.36)'), { payload: 'C' + c + '\n' }];
    }
    context.set('armedCells', { c: c, at: now });
    return [null, null, null, ui('Click again within 10 s to set ' + c + ' cells in series (' + (c === 6 ? '24' : '48') + ' V)'), null];
}
if (t === 'kbit') {
    // CAN speed of the Teensy (kbit/s). Double click (10 s).
    const k = [125, 250, 500, 1000].includes(Number(msg.payload)) ? Number(msg.payload) : 0;
    if (!k) return [null, null, null, ui('CAN speed: invalid value'), null];
    const armed = context.get('armedKbit') || {};
    if (armed.k === k && (now - armed.at) < 10000) {
        context.set('armedKbit', {});
        return [null, null, null, ui('CAN speed sent: ' + k + ' kbit/s - the CAN bus panel shows it within a few seconds (needs firmware v26.35)'), { payload: 'K' + k + '\n' }];
    }
    context.set('armedKbit', { k: k, at: now });
    return [null, null, null, ui('Click again within 10 s to set the CAN speed to ' + k + ' kbit/s. All devices on the bus must use the same speed!'), null];
}
if (t === 'proto') {
    // CAN protocol to the inverter: 0 Victron, 1 LG RESU LV (SolarEdge). Double click (10 s).
    const p = Number(msg.payload) === 1 ? 1 : 0;
    const armed = context.get('armedProto') || {};
    if (armed.p === p && (now - armed.at) < 10000) {
        context.set('armedProto', {});
        return [null, null, null, ui('CAN protocol sent: ' + (p ? 'LG RESU LV (SolarEdge)' : 'Victron') + ' - the overview header shows it within a few seconds (needs firmware v26.29)'), { payload: 'P' + p + '\n' }];
    }
    context.set('armedProto', { p: p, at: now });
    return [null, null, null, ui('Click again within 10 s to switch the CAN protocol to ' + (p ? 'LG RESU LV (SolarEdge)' : 'Victron') + '. Victron/SolarEdge only work with the matching protocol!'), null];
}
if (t === 'bal') {
    // balancing start/stop difference (mV) -> direct command "B<start>,<stop>" to the Teensy (saved in EEPROM)
    const p = msg.payload || {};
    const a = Math.round(Number(p.start)), b = Math.round(Number(p.stop)), v = Math.round(Number(p.from));
    if (!(b >= 2 && b <= 50 && a > b && a <= 100)) return [null, null, null, ui('Balancing: invalid values'), null];
    if (!(v >= 3300 && v <= 4150)) return [null, null, null, ui('Balancing: from cell voltage 3300-4150 mV'), null];
    node.status({ fill: 'blue', shape: 'dot', text: `balancing from ${v} mV, ${a}/${b} mV` });
    return [null, null, null, ui(`Balancing sent: from cell > ${v} mV, start > ${a} mV, down to ${b} mV - the Balancing tile shows the new values within a few seconds (the from voltage needs firmware v26.37)`), { payload: `B${a},${b},${v}\n` }];
}
if (t === 'fw' || t === 'flow') {
    if (flow.get('teslabmsBusy')) return [null, null, null, ui('An update is already running - please wait')];
    const gb = global.get('teslabmsFlashBusy') || 0;
    if (now - gb < 300000) return [null, null, null, ui('A firmware update of the other Teensy is running - please wait')];
    const armed = context.get('armed') || {};
    if (armed.t === t && (now - armed.at) < 10000) {
        context.set('armed', {});
        flow.set('teslabmsBusy', true);
        if (t === 'fw') {
            node.status({ fill: 'yellow', shape: 'dot', text: 'flashing Teensy...' });
            const hw = flow.get('teensyHw') || 'auto';   // model of the running firmware; unknown: the flash script reads it in the bootloader
            const port = flow.get('teensyPort');   // exactly this Teensy (there can be more than one)
            if (!port) { flow.set('teslabmsBusy', false); return [null, null, null, ui('Teensy port unknown - wait until data arrives')]; }
            global.set('teslabmsFlashBusy', now);
            return [null, { payload: '--board ' + hw + ' --port ' + port }, null, ui('Teensy firmware update running (BMS off for a few seconds)...')];
        }
        node.status({ fill: 'yellow', shape: 'dot', text: 'updating dashboard...' });
        return [null, null, { payload: '' }, ui('Dashboard update running - Node-RED restarts; reload this page after about 30 s.')];
    }
    context.set('armed', { t: t, at: now });
    const name = t === 'fw' ? 'Update Teensy firmware' : 'Update dashboard';
    return [null, null, null, ui('Click "' + name + '" again within 10 seconds to confirm.')];
}
return null;

