D=/data/teslabms; mkdir -p $D 2>/dev/null; [ -w $D ] || { D=${HOME:-/data/home/nodered}/teslabms; mkdir -p $D; }; cd $D && echo "DIR=$D" && python3 -c "
import urllib.request, os
for f in ('teensy_flash.py', 'flow_update.py', 'solaredge_ctl.py'):
    u = 'https://github.com/AncoDiara/TeslaBMSV2.1/releases/latest/download/' + f
    try:
        d = urllib.request.urlopen(urllib.request.Request(u, headers={'User-Agent': 'teslabms'}), timeout=30).read()
        open(f + '.tmp', 'wb').write(d); os.replace(f + '.tmp', f)
    except Exception as e:
        print('DL-ERROR', f, e)
"; echo "FW=$(python3 teensy_flash.py --check --no-serial 2>/dev/null)"; echo "FLOW=$(python3 flow_update.py --check 2>/dev/null)"

func:
// Output of "check versions": lines FW=<json> and FLOW=<json>.
const out = String(msg.payload || '');
const grab = (k) => {
    const m = out.match(new RegExp('^' + k + '=(.*)$', 'm'));
    if (!m) return null;
    try { return JSON.parse(m[1]); } catch (e) { return null; }
};
const fw = grab('FW') || {};
const fl = grab('FLOW') || {};
const dl = out.match(/^DL-ERROR (.*)$/m);
const rcErr = (msg.rc && msg.rc.code) ? ('check script failed (code ' + msg.rc.code + (msg.rc.signal ? ', ' + msg.rc.signal : '') + ')') : null;
const info = {
    running: flow.get('teensyFw') || fw.running || null,     // from the JSON output of the Teensy
    board: flow.get('teensyHw') || null,                      // T32 / T40 / T41
    latestFw: fw.latest || null,
    flowInstalled: env.get('TESLABMS_FLOW_VERSION') || fl.installed || null,
    latestFlow: fl.latest || null,
    error: fw.error || fl.error || (dl ? 'Download of the update scripts failed: ' + dl[1].trim() : null) || rcErr
};
const d = new Date();
const pad = (x) => String(x).padStart(2, '0');
const when = pad(d.getHours()) + ':' + pad(d.getMinutes());
const newer = (info.latestFw && info.running && info.latestFw !== info.running) ||
              (info.latestFlow && info.flowInstalled && info.latestFlow !== info.flowInstalled);
const state = info.error ? ('Check failed at ' + when)
            : (!info.latestFw || !info.latestFlow) ? ('Checked at ' + when + ' - latest version unknown')
            : newer ? ('Checked at ' + when + ' - update available')
            : ('Checked at ' + when + ' - everything up to date');
flow.set('teslabmsChecking', false);
if (info.latestFw) global.set('teslabmsLatestFw', info.latestFw);   // also for the test bench tab
node.status({ fill: info.error ? 'red' : 'green', shape: 'dot', text: when + ' fw ' + info.running + ' / ' + info.latestFw + ', flow ' + info.flowInstalled + ' / ' + info.latestFlow });
// one message with info AND state, so a page reload (last message replayed) is consistent
return { payload: { kind: 'info', info: info, state: state } };

// Result of "flash Teensy" or "update dashboard".
flow.set('teslabmsBusy', false);
global.set('teslabmsFlashBusy', 0);
const out = String(msg.payload || '').trim();
const failed = /ERROR/.test(out) || (msg.rc && msg.rc.code);
const state = failed ? 'Update FAILED - see the log below' : 'Update finished';
// after 25 s check the versions again (the Teensy has to start up first)
return [{ payload: { kind: 'log', text: out, state: state } }, { topic: 'check' }];

// Patient JSON watchdog (flow v26.48). Node-RED does NOT keep sending commands to the Teensy:
// every byte would keep an open menu open (a technician at work, or stray bytes).
//   JSON arrives                          -> nothing to do
//   text, but no JSON for 3 min           -> 'J' once (JSON on); again at most every 10 min
//   completely silent for 5 min           -> warning only (cable, technician, Teensy off);
//                                            'J' at most every 15 min (closes a menu from fw v26.37)
const now = Date.now();
const last = flow.get('teensyLastData') || 0;
const text = flow.get('teensyLastText') || 0;
const sent = context.get('sent') || 0;
const ago = (t) => t ? Math.round((now - t) / 60000) + ' min' : 'never';
if (now - last < 180000) {
    node.status({ fill: 'green', shape: 'dot', text: 'JSON is arriving' });
    return null;
}
if (text > last && now - text < 180000) {
    if (now - sent > 600000) {
        context.set('sent', now);
        node.status({ fill: 'yellow', shape: 'ring', text: 'text instead of JSON - sent J' });
        return { payload: 'J\n' };
    }
    node.status({ fill: 'yellow', shape: 'ring', text: 'text instead of JSON (J sent ' + ago(sent) + ' ago)' });
    return null;
}
if (now - Math.max(last, text) > 300000 && now - sent > 900000) {
    context.set('sent', now);
    node.status({ fill: 'red', shape: 'ring', text: 'Teensy silent for ' + ago(Math.max(last, text)) + ' - sent J' });
    return { payload: 'J\n' };
}
node.status({ fill: 'yellow', shape: 'ring', text: 'no JSON for ' + ago(last) });
return null;

// DVCC charge voltage limit from the GX (dbus):
// LIM = Settings -> DVCC -> "Limit charge voltage" (0 = off).
const out = String(msg.payload || '');
const m = out.match(/^LIM=(.*)$/m);
const v = m ? parseFloat(m[1]) : NaN;
const lim = isNaN(v) ? null : v;
const dvcc = { lim: (lim && lim > 0) ? lim : null, limOff: lim === 0, ts: Date.now() };
flow.set('dvcc', dvcc);
node.status({ fill: 'green', shape: 'dot', text: 'DVCC limit ' + (dvcc.lim !== null ? dvcc.lim + ' V' : (dvcc.limOff ? 'off' : '?')) });
return null;

// Saved assignment of the Teensys (USB serial numbers): { main, test }
try {
    const r = JSON.parse(msg.payload);
    if (r && typeof r === 'object') {
        global.set('teensyRoles', r);
        node.status({ fill: 'green', shape: 'dot', text: 'main ' + (r.main || '-') + '  test ' + (r.test || '-') });
    }
} catch (e) {
    node.status({ fill: 'red', shape: 'ring', text: 'roles file invalid' });
}
return null;

// One line of serial output from the Teensy.
// Only lines that start with '{' are the JSON telemetry (menu m -> j on the Teensy);
// all other lines (menus, messages) are ignored.
const line = String(msg.payload || '').trim();
if (!line.startsWith('{')) {
    // text (start banner, menu, messages): the Teensy lives, but sends no JSON right now
    if (line) flow.set('teensyLastText', Date.now());
    return null;
}
let d;
try {
    d = JSON.parse(line);
} catch (e) {
    node.status({ fill: 'red', shape: 'ring', text: 'invalid JSON' });
    return null;
}
d._ts = Date.now();
d._dvcc = null;   // test bench: no GX/DVCC
flow.set('teensyLastData', d._ts);
flow.set('teensyFw', 'v' + d.fw);
flow.set('teensyHw', d.hw || 'T32');   // Teensy model (firmware before v26.26 has no hw field: always a Teensy 3.2)
// Report this Teensy for the port assignment ("Assign Teensy ports" in the main tab)
const sm = String(flow.get('teensyPort') || '').match(/_([0-9A-Za-z]+)-if\d+$/);
if (sm) {
